mapper.select:
SELECT *
  FROM api_key
WHERE domain = #{domain}
ORDER BY created;

SELECT *
  FROM api_key
WHERE domain = #{domain}
  AND created > #{created}
ORDER BY created;

SELECT count(*)
  FROM api_key
 WHERE domain = #{domain};

mapper.update:
INSERT INTO api_key (primary_principal
                    , domain
                    , token
                    , principals
                    , created)
VALUES (#{primaryPrincipal, typeHandler=EncryptedStringTypeHandler}
        , #{domain}
        , #{token}
        , #{principals}
        , #{created})
ON CONFLICT (domain, token)
DO UPDATE SET
  token = EXCLUDED.token
  , primary_principal = EXCLUDED.primary_principal
  , principals = EXCLUDED.principals
  , created = EXCLUDED.created;

 MERGE INTO api_key (primary_principal, domain, token,
                     principals , created)
   KEY (domain, token)
VALUES (#{primaryPrincipal, typeHandler=EncryptedStringTypeHandler}
        , #{domain}
        , #{token}
        , #{principals}
        , #{created});

mapper.select:
SELECT *
FROM api_key
WHERE domain = #{domain}
ORDER BY created
LIMIT #{limit}
OFFSET #{skip};

  SELECT *
    FROM api_key
   WHERE created > #{created}
ORDER BY created
   LIMIT #{limit};
